const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

console.log('[Vercel Build] 1. Installing client dependencies...');
execSync('npm --prefix client install', { stdio: 'inherit' });

console.log('[Vercel Build] 2. Building Nuxt client...');
execSync('npm --prefix client run build', { stdio: 'inherit' });

// Sync .vercel/output from client to root if generated by Nitro Vercel preset
const clientVercel = path.join(__dirname, '..', 'client', '.vercel', 'output');
const rootVercel = path.join(__dirname, '..', '.vercel', 'output');

if (fs.existsSync(clientVercel)) {
  console.log('[Vercel Build] 3. Copying client/.vercel/output to root .vercel/output...');
  fs.cpSync(clientVercel, rootVercel, { recursive: true });
}

// Sync client/.output to root .output for standard Nitro output
const clientOutput = path.join(__dirname, '..', 'client', '.output');
const rootOutput = path.join(__dirname, '..', '.output');

if (fs.existsSync(clientOutput)) {
  console.log('[Vercel Build] 4. Copying client/.output to root .output...');
  fs.cpSync(clientOutput, rootOutput, { recursive: true });
}

console.log('[Vercel Build] Completed successfully!');
